/**
 * secrets-veil must never return a tool result unmasked, even when the mod
 * never saw session.start (enabled or hot-reloaded mid-session). This file
 * runs in its own module instance (vitest isolates per file), so `table`
 * starts null, and every $.env.get throws: the lazy arm must fall back to
 * shapes and entropy, never to pass-through.
 */

import { describe, test, expect } from "vitest";
import { register } from "../hooks/register.js";

type RegisteredHook = (...args: unknown[]) => unknown;

// A fake GitHub token shape, assembled at runtime so no token-shaped literal
// sits in the source: the ghp_ prefix plus 36 filler characters.
const FAKE_GH = "gh" + "p_" + "Zq8Lm3Rt7Vx2Kp9Nw4Hy6Bc1Df5Gj0Sa8Ue3";

/** Synthetic named value: no vendor shape, low entropy, so only the named path masks it. */
const SYNTHETIC = "veiltest-synthetic-value-42";

/** .catch handlers the module registered, by event. */
const catches = new Map<string, (...args: unknown[]) => unknown>();

function hooksOf(): Map<string, RegisteredHook> {
  const hooks = new Map<string, RegisteredHook>();
  register((event: string, hook: unknown) => {
    hooks.set(event, hook as RegisteredHook);
    // The engine's registration: on() returns an object that takes one .catch.
    return { catch: (handler: (...args: unknown[]) => unknown) => catches.set(event, handler) };
  }, {});
  return hooks;
}

function fake$(env: Record<string, string> | "throws"): unknown {
  return {
    env: {
      get: async (name: string): Promise<string | undefined> => {
        if (env === "throws") throw new Error(`env.get(${name}) refused`);
        return env[name];
      },
    },
    ui: {
      notice: async (): Promise<void> => undefined,
      toast: async (): Promise<void> => undefined,
      status: async (): Promise<void> => undefined,
      log: async (): Promise<void> => undefined,
    },
  };
}

const next = (result: unknown) => async (): Promise<unknown> => result;

describe("fail closed when the lazy arm cannot read the environment", () => {
  test("shapes and entropy still mask when every env read throws and session.start never ran", async () => {
    const hooks = hooksOf();
    const out = await hooks.get("tool.call")!(
      fake$("throws"),
      { tool: "Bash", args: {} },
      next({ result: { stdout: `FAKE_TOKEN=${FAKE_GH}\n` } })
    );
    expect(JSON.stringify(out)).not.toContain(FAKE_GH);
    expect(JSON.stringify(out)).toContain("\u2022".repeat(8));
  });
});
